<?php declare(strict_types=1); ?>
<section class="module-toolbar"><div><p class="module-intro">Oturumları, başarısız giriş denemelerini ve güvenlik olaylarını izleyin.</p></div><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="revoke_others"><button class="btn secondary">Diğer oturumlarımı kapat</button></form></section>
<section class="panel customer-list-panel"><h3>Aktif kullanıcı oturumları</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Kullanıcı</th><th>IP</th><th>Tarayıcı</th><th>Son aktivite</th><th>Oluşturulma</th><th></th></tr></thead><tbody><?php foreach($sessions as $s): ?><tr><td><?= kd_e($s['name']) ?><small class="table-sub"><?= kd_e($s['email']) ?></small></td><td><?= kd_e($s['ip_address']) ?></td><td><?= kd_e(mb_substr($s['user_agent'],0,70)) ?></td><td><?= kd_e($s['last_activity']) ?></td><td><?= kd_e($s['created_at']) ?></td><td><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="revoke"><input type="hidden" name="session_id" value="<?= (int)$s['id'] ?>"><button class="btn secondary">Oturumu kapat</button></form></td></tr><?php endforeach; ?><?php if(!$sessions): ?><tr><td colspan="6">Aktif oturum yok.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel customer-list-panel"><h3>Son 24 saat · başarısız girişler</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>IP adresi</th><th>Deneme sayısı</th><th>Son deneme</th></tr></thead><tbody><?php foreach($attempts as $a): ?><tr><td><?= kd_e($a['ip_address']) ?></td><td><?= (int)$a['attempts'] ?></td><td><?= kd_e($a['last_attempt']) ?></td></tr><?php endforeach; ?><?php if(!$attempts): ?><tr><td colspan="3">Başarısız giriş kaydı yok.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel customer-list-panel"><h3>Güvenlik olayları</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Tarih</th><th>Kullanıcı</th><th>Olay</th><th>Önem</th><th>Mesaj</th></tr></thead><tbody><?php foreach($events as $e): ?><tr><td><?= kd_e($e['created_at']) ?></td><td><?= kd_e($e['user_name']??'Sistem') ?></td><td><?= kd_e($e['event_type']) ?></td><td><?= kd_e($e['severity']) ?></td><td><?= kd_e($e['message']) ?></td></tr><?php endforeach; ?><?php if(!$events): ?><tr><td colspan="5">Güvenlik olayı yok.</td></tr><?php endif; ?></tbody></table></div></section>
